const CSAT_FORM_WEBHOOK_PATH = '2b510c06-fa2c-4122-980e-27b92f7c6ab1';

const incoming = $input.first().json || {};
return [{ json: { ...incoming, csatFormPath: CSAT_FORM_WEBHOOK_PATH } }];

const formPathCfg = $('CSAT Form Path Config').first().json;
const cfg = { ...$('Parse Jira CSAT Webhook').first().json.config, csatFormPath: formPathCfg.csatFormPath };

function pickJiraField(fields, fieldId) {
  if (!fieldId || String(fieldId).includes('REPLACE_')) return '';
  const v = fields[fieldId];
  if (v == null || v === '') return '';
  if (typeof v === 'object' && v.value != null) return String(v.value).trim();
  return String(v).trim();
}

function resolveWhatsAppChatId(phoneFieldValue) {
  const raw = String(phoneFieldValue || '').trim();
  if (!raw) return '';
  if (raw.includes('@')) return raw;
  const digits = raw.replace(/\D/g, '');
  return digits ? `${digits}@c.us` : '';
}

function resolveWahaSession(stampedSession, cfg) {
  const fromField = String(stampedSession || '').trim();
  if (/^session_[a-z0-9]+$/i.test(fromField)) return fromField;
  const fromCfg = String(cfg.wahaSession || '').trim();
  if (/^session_[a-z0-9]+$/i.test(fromCfg)) return fromCfg;
  return '';
}

function buildWahaOutbound({ wahaBaseUrl, wahaSession, whatsappChatId, messageText }) {
  const base = String(wahaBaseUrl || 'https://waha.intuz.net').replace(/\/$/, '');
  const session = resolveWahaSession(wahaSession, cfg);
  const chatId = resolveWhatsAppChatId(whatsappChatId);
  const text = String(messageText || '').slice(0, 3900);
  return {
    wahaBaseUrl: base,
    wahaSession: session,
    whatsappChatId: chatId,
    _wahaSendUrl: `${base}/api/sendText`,
    _wahaSendBody: { session, chatId, text }
  };
}

const webhook = $('Parse Jira CSAT Webhook').first().json || {};
const issue = $input.first().json || {};
const fields = issue.fields || {};
const key = webhook.jiraKey || issue.key || '';

if (!webhook.canProceed) {
  return [{ json: { ...webhook, canSend: false, skipReason: webhook.skipReason || 'webhook_rejected' } }];
}

const cf = cfg.jira?.customFields || {};
const labels = Array.isArray(fields.labels) ? fields.labels.map(String) : [];

let channel = pickJiraField(fields, cf.channel).toLowerCase();
if (!channel) {
  const chLabel = labels.find((l) => l.startsWith('channel-'));
  if (chLabel) channel = chLabel.replace(/^channel-/, '');
}

const email = pickJiraField(fields, cf.customerEmail).toLowerCase();
const phoneField = pickJiraField(fields, cf.customerPhone);
const whatsappChatId = resolveWhatsAppChatId(phoneField);
const hubspotContactId = pickJiraField(fields, cf.hubspotContactId) || null;
const stampedWahaSession = pickJiraField(fields, cf.wahaSession);
const wahaSession = resolveWahaSession(stampedWahaSession, cfg);
const wahaBaseUrl = String(cfg.wahaBaseUrl || 'https://waha.intuz.net').replace(/\/$/, '');

const formPath = formPathCfg.csatFormPath;
const formUrl = `${String(cfg.n8nPublicBaseUrl || '').replace(/\/$/, '')}/form/${formPath}?ticket=${encodeURIComponent(key)}`;
const messageText = `Hello,\n\nYour support ticket ${key} has been marked as resolved.\n\nHow satisfied were you with our support? Please rate us using this short form (1 = poor, 5 = excellent):\n${formUrl}\n\nThank you for your feedback!`.slice(0, 3900);

let canSend = false;
let skipReason = '';
if (channel === 'whatsapp') {
  canSend = !!whatsappChatId && !!wahaSession;
  if (!canSend) skipReason = 'missing_whatsapp_chat_id_or_waha_session';
} else if (channel === 'gmail' || channel === 'form' || !channel) {
  channel = channel || 'form';
  canSend = !!email;
  if (!canSend) skipReason = 'missing_email';
} else {
  skipReason = 'unknown_channel';
}

const wahaOutbound = channel === 'whatsapp'
  ? buildWahaOutbound({ wahaBaseUrl, wahaSession, whatsappChatId: phoneField, messageText })
  : {};

return [{
  json: {
    event: 'ticket_done',
    config: cfg,
    jiraKey: key,
    channel,
    email,
    phone: phoneField.replace(/@.+$/, '').replace(/\D/g, '') || phoneField,
    whatsappChatId: wahaOutbound.whatsappChatId || whatsappChatId,
    wahaSession: wahaOutbound.wahaSession || wahaSession,
    wahaBaseUrl: wahaOutbound.wahaBaseUrl || wahaBaseUrl,
    hubspotContactId,
    messageText,
    ...wahaOutbound,
    emailSubject: `[Support-Auto] How did we do? — Ticket ${key}`,
    formUrl,
    canSend,
    skipReason,
    isDone: webhook.isDone,
    transitionedToDone: webhook.transitionedToDone,
    alreadySent: webhook.alreadySent,
    _contactSource: 'jira_custom_fields',
    _wahaSessionSource: stampedWahaSession ? 'jira_custom_field' : 'workflow_config'
  }
}];

const d = $input.first().json || {};
const cfg = d.config || {};
const base = String(cfg.jiraBaseUrl || 'https://intuzdev5.atlassian.net').replace(/\/$/, '');
const key = d.jiraKey;
