  return [{ json: { ...prev, hubspotNoteSkipped: true } }];
}
return [{
  json: {
    ...prev,
    hubspotNoteId: noteId,
    _hsAssocBody: {
      inputs: [{
        from: { id: String(noteId) },
        to: { id: String(prev.hubspotContactId) },
        type: 'note_to_contact'
      }]
    }
  }
}];

const d = $input.first().json;
const contactId = d.hubspotContactId;
if (!contactId) {
  return [{ json: { ...d, _hsSkipNote: true } }];
}

let body = '';
if (d.event === 'ticket_created') {
  body = `Support ticket created: ${d.jiraKey}\nChannel: ${d.channel}\nURL: ${d.jiraUrl}\nCategory: ${d.category || 'N/A'}\nPriority: ${d.priority || 'N/A'}\nSummary: ${d.summary || ''}\nCustomer auto-reply sent.`;
} else if (d.event === 'csat_submitted') {
  body = `CSAT received for ${d.jiraKey}: ${d.csatScore}/5\nComment: ${d.csatComment || '(none)'}`;
} else {
  body = `Support update for ${d.jiraKey}`;
}

return [{
